const BUILTIN_POLICIES = new Set(['DIRECT', 'REJECT']);
const DIRECT_NODE_SELECT_EXCLUDES = new Set(['🚀 手动切换', '🎥 奈飞节点', '🛑 广告拦截', '🍃 应用净化']);

function uniq(items) {
  return [...new Set(items.filter(Boolean))];
}

function normalizeVlessProxy(proxy) {
  if (!proxy || typeof proxy !== 'object') return proxy;
  if (String(proxy.type || '').toLowerCase() !== 'vless') return proxy;

  // Mihomo defaults udp=false. Force VLESS nodes to accept application UDP,
  // and encode it as XUDP inside the existing VLESS transport. For the user's
  // Vision + REALITY nodes the outer transport remains TCP (or TCP by default).
  return { ...proxy, udp: true, 'packet-encoding': 'xudp' };
}

function matchNodes(names, patterns) {
  if (!patterns.length) return [];
  const out = [];
  for (const pattern of patterns) {
    let re;
    try { re = new RegExp(pattern, 'i'); }
    catch (e) { throw new Error('[ACL4SSR override] Invalid upstream regex ' + pattern + ': ' + e.message); }
    for (const name of names) if (re.test(name)) out.push(name);
  }
  return uniq(out);
}

function resolveActiveGroups(nodeNames) {
  const matches = new Map(GROUP_SPECS.map((spec) => [spec.name, matchNodes(nodeNames, spec.patterns)]));
  const active = new Set();
  let changed = true;

  // A group is active only if it is grounded by at least one real node/builtin
  // or references another already-grounded group. This also collapses empty
  // dependency chains instead of leaving REJECT placeholders behind.
  while (changed) {
    changed = false;
    for (const spec of GROUP_SPECS) {
      if (active.has(spec.name)) continue;
      const hasNodes = (matches.get(spec.name) || []).length > 0;
      const hasGroundedRef = spec.refs.some((ref) => BUILTIN_POLICIES.has(ref) || active.has(ref));
      if (hasNodes || hasGroundedRef) {
        active.add(spec.name);
        changed = true;
      }
    }
  }

  return { active, matches };
}

function shouldExposeDirectNodes(spec) {
  if (spec.type !== 'select' || DIRECT_NODE_SELECT_EXCLUDES.has(spec.name)) return false;
  // Business select groups reference other policies; helper filters usually only
  // carry regex patterns. Expose real nodes in business groups without breaking
  // filtered helpers such as Netflix-only nodes.
  return spec.refs.length > 0 || spec.patterns.length === 0;
}

function buildGroup(spec, active, matches, nodeNames) {
  const refs = spec.refs.filter((ref) => BUILTIN_POLICIES.has(ref) || active.has(ref));
  const directNodes = shouldExposeDirectNodes(spec) ? nodeNames : [];
  const proxies = uniq([...refs, ...(matches.get(spec.name) || []), ...directNodes]);
  if (!proxies.length) return null;

  if (spec.type === 'select') return { name: spec.name, type: 'select', proxies };
  if (spec.type === 'url-test' || spec.type === 'fallback') {
    return { name: spec.name, type: spec.type, proxies, url: spec.url || 'http://www.gstatic.com/generate_204', interval: spec.interval || 300, tolerance: spec.tolerance || 50 };
  }
  if (spec.type === 'load-balance') {
    return { name: spec.name, type: 'load-balance', proxies, url: spec.url || 'http://www.gstatic.com/generate_204', interval: spec.interval || 300, strategy: spec.strategy || 'consistent-hashing' };
  }
  throw new Error('[ACL4SSR override] Unsupported group type: ' + spec.type);
}

function main(config) {
  if (!config || !Array.isArray(config.proxies) || config.proxies.length === 0) {
    throw new Error('[ACL4SSR override] config.proxies is empty; use this script on a Clash/Mihomo file generated from Sub-Store nodes.');
  }
  const proxies = config.proxies.map(normalizeVlessProxy);
  const nodeNames = proxies.map((p) => p && p.name).filter(Boolean);
  const { active, matches } = resolveActiveGroups(nodeNames);
  const proxyGroups = GROUP_SPECS
    .filter((spec) => active.has(spec.name))
    .map((spec) => buildGroup(spec, active, matches, nodeNames))
    .filter(Boolean);
  // Resolve every rule target AFTER empty-region/helper groups have been pruned.
  // Personal country rules such as personal-jp must not reference vanished
  // country groups. Keep a real node selector as the safe proxy fallback.
  const policies = new Set(['DIRECT', 'REJECT', ...proxyGroups.map(g => g.name)]);
  const definedGroups = new Set(GROUP_SPECS.map(spec => spec.name));
  const resolvedRules = RULES.map(line => {
    const at = line.lastIndexOf(',');
    if (at < 0) throw new Error('[ACL4SSR override] Invalid generated rule: ' + line);
    const policy = line.slice(at + 1).trim();
    if (policies.has(policy)) return line;
    if (!definedGroups.has(policy)) {
      throw new Error('[ACL4SSR override] Rule targets unknown policy: ' + line);
    }
    if (!policies.has('🚀 节点选择')) {
      throw new Error('[ACL4SSR override] Main node selector missing for pruned rule: ' + line);
    }
    return line.slice(0, at + 1) + '🚀 节点选择';
  });
  for (const line of resolvedRules) {
    if (!policies.has(line.slice(line.lastIndexOf(',') + 1).trim())) {
      throw new Error('[ACL4SSR override] Rule still targets missing group: ' + line);
    }
  }
  return { ...config, proxies, 'proxy-groups': proxyGroups, 'rule-providers': RULE_PROVIDERS, rules: resolvedRules };
}

globalThis.main = main;
